            background: #f0f0f0;
            border-radius: 5px;
        }

        .next-piece h3 {
            color: #333;
            margin-bottom: 10px;
            font-size: 14px;
        }

        .next-grid {
            display: grid;
            grid-template-columns: repeat(4, 20px);
            grid-gap: 1px;
            background: #ddd;
            padding: 3px;
        }

        .next-grid .cell {
            width: 20px;
            height: 20px;
        }

        .buttons {
            display: flex;
            flex-direction: column;
